-- Migration 047: sesta tornata di contenuti News (12 articoli), con date che
-- proseguono la cadenza della migration 044 (circa un articolo ogni 1,75
-- giorni) dal 12/09 all'1/10/2026, categorie a rotazione fissa mutui ->
-- investimenti -> budget -> pianificazione e seo_title (migration 045).
-- Link interni senza estensione .php (migration 046).
--
-- Corregge anche un'inesattezza in tassazione-investimenti-etf-azioni-italia:
-- le plusvalenze degli ETF sono redditi di capitale, non redditi diversi,
-- quindi non possono compensare le minusvalenze (le perdite su ETF sì,
-- possono essere compensate da plusvalenze su azioni, obbligazioni, ETC).
-- È una correzione del contenuto: updated_at si aggiorna di proposito.

UPDATE news_articles SET body = REPLACE(body,
    'compensare future plusvalenze dello stesso tipo (i cosiddetti redditi diversi, come quelli da ETF e azioni), entro il quarto anno solare successivo.',
    'compensare future plusvalenze dello stesso tipo (i cosiddetti redditi diversi, come le plusvalenze su azioni, obbligazioni ed ETC), entro il quarto anno solare successivo. Attenzione: le plusvalenze degli ETF sono invece redditi di capitale e non possono assorbire le minusvalenze accumulate.'),
    updated_at = NOW()
WHERE slug = 'tassazione-investimenti-etf-azioni-italia'
  AND body LIKE '%(i cosiddetti redditi diversi, come quelli da ETF e azioni)%';

INSERT INTO news_articles
    (slug, title, seo_title, excerpt, meta_description, category, cover_emoji, body, status, published_at, updated_at)
VALUES
(
    'quanto-mutuo-posso-chiedere-con-il-mio-stipendio',
    'Quanto mutuo posso chiedere con il mio stipendio? Il calcolo che fanno le banche',
    'Quanto mutuo posso chiedere con il mio stipendio?',
    'Le banche non guardano solo il prezzo della casa ma soprattutto quanto pesa la rata sul tuo reddito. Ecco la regola di massima che usano e come stimare il mutuo che puoi ottenere.',
    'Quanto mutuo puoi chiedere in base allo stipendio: la regola della rata a un terzo del reddito ed esempi con 1.500, 2.000 e 2.500 euro netti al mese.',
    'mutui',
    '💶',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima ancora di cercare casa, la domanda più utile da farsi è quanto mutuo puoi ottenere davvero. Non lo decide il prezzo dell''immobile ma il tuo reddito: la banca vuole essere ragionevolmente sicura che potrai pagare la rata per tutta la durata del prestito, anche se nel frattempo arrivano imprevisti.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La regola della rata a un terzo del reddito</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La maggior parte delle banche parte da una regola di massima: la <strong>rata del mutuo non dovrebbe superare circa un terzo del reddito netto mensile</strong> del nucleo che chiede il prestito, cioè il 30-35%. Se hai già altri finanziamenti, le loro rate si sommano a quella del mutuo nel calcolo. È lo stesso principio del <a href="/news/rapporto-debito-reddito-dti-cosa-e" class="text-accent hover:underline font-medium">rapporto debito/reddito</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Qualche esempio</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con un tasso del 3% (solo un esempio: il tasso reale dipende dal mercato e dalla banca), applicando la regola del terzo si ottengono più o meno questi importi:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>1.500 € netti al mese</strong>: rata massima intorno a 500 €, cioè circa 105.000 € in 25 anni o 118.000 € in 30 anni.</li><li><strong>2.000 € netti al mese</strong>: rata massima intorno a 667 €, circa 140.000 € in 25 anni o 158.000 € in 30 anni.</li><li><strong>2.500 € netti al mese</strong>: rata massima intorno a 833 €, circa 175.000 € in 25 anni o 197.000 € in 30 anni.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Allungare la durata aumenta l''importo ottenibile, ma anche il totale degli interessi pagati: lo vedi bene nel piano di <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa conta oltre allo stipendio</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>L''anticipo</strong>: di solito la banca finanzia fino all''80% del valore dell''immobile, come spiega la guida al <a href="/news/loan-to-value-ltv-mutuo-quanto-puoi-finanziare" class="text-accent hover:underline font-medium">loan to value</a>. Il resto, più le <a href="/news/spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa" class="text-accent hover:underline font-medium">spese accessorie</a>, va coperto con i risparmi.</li><li><strong>La stabilità del reddito</strong>: un contratto a tempo indeterminato pesa più di un reddito variabile o recente.</li><li><strong>L''età</strong>: la durata massima è spesso limitata in modo che il mutuo finisca entro una certa età.</li><li><strong>La storia creditizia</strong>: ritardi passati nei pagamenti possono ridurre l''importo o portare a un rifiuto.</li><li><strong>Un secondo intestatario</strong>: con un <a href="/news/mutuo-cointestato-come-funziona" class="text-accent hover:underline font-medium">mutuo cointestato</a> i redditi si sommano.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quanto è prudente chiedere</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il massimo che la banca concede non è per forza quello che conviene chiedere. Una rata al limite lascia poco margine per il <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a> e per il risparmio. Prima di decidere, prova a vivere per qualche mese mettendo da parte l''equivalente della rata futura: se non ci riesci con serenità, è un segnale da ascoltare.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/mutui" class="text-accent hover:underline font-medium">Reflexi</a> puoi inserire il mutuo e vedere come la rata si inserisce nel resto del tuo budget, mese per mese.</p>',
    'pubblicato',
    '2026-09-12 09:00:00',
    '2026-09-12 09:00:00'
),
(
    'asset-allocation-cos-e-come-sceglierla',
    'Asset allocation: cos''è e come scegliere la ripartizione giusta del portafoglio',
    'Asset allocation: cos''è e come sceglierla',
    'Quanto in azioni, quanto in obbligazioni, quanto in liquidità: la ripartizione tra classi di attivo spiega gran parte del comportamento di un portafoglio. Ecco come ragionarci.',
    'Cos''è l''asset allocation e come sceglierla tra azioni, obbligazioni e liquidità in base a orizzonte e rischio, con esempi di portafogli prudenti e dinamici.',
    'investimenti',
    '🧩',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando si parla di investimenti, l''attenzione va quasi sempre al singolo titolo o al singolo ETF. Eppure la decisione che conta di più viene prima: <strong>quanto del tuo capitale mettere in ciascuna classe di attivo</strong>. È quella che determina quanto oscillerà il portafoglio e, in buona parte, quanto potrà rendere nel lungo periodo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è l''asset allocation</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''asset allocation è la ripartizione del portafoglio tra grandi categorie di investimento, con caratteristiche di rischio e rendimento diverse:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Azioni</strong>: il rendimento atteso più alto nel lungo periodo, ma anche le oscillazioni più ampie.</li><li><strong>Obbligazioni</strong>: più stabili, rendono meno e attenuano i ribassi del portafoglio. Un esempio sono i <a href="/news/btp-titoli-di-stato-come-funzionano" class="text-accent hover:underline font-medium">titoli di Stato</a>.</li><li><strong>Liquidità</strong>: nessuna oscillazione, ma rende poco e soffre l''inflazione. Si può tenere anche in <a href="/news/etf-monetari-o-conto-deposito" class="text-accent hover:underline font-medium">ETF monetari o conti deposito</a>.</li><li><strong>Altri attivi</strong>, come materie prime o immobili, da valutare con cautela e di solito in quota minore.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come sceglierla</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">L''orizzonte temporale</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più lontano è il momento in cui ti serviranno i soldi, più rischio puoi permetterti: hai il tempo per recuperare un ribasso. Per un obiettivo a due o tre anni le azioni sono in genere poco adatte; per la pensione tra trent''anni possono essere la parte principale.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">La tolleranza al rischio</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non conta solo quanto rischio puoi sopportare sulla carta, ma quanto ne reggi davvero. Se un calo del 30% ti spingerebbe a vendere tutto, quel portafoglio è troppo aggressivo per te, qualunque sia il tuo orizzonte. Ricorda che recuperare una perdita richiede un rialzo più ampio, come spieghiamo nell''articolo sul <a href="/news/recupero-perdite-perche-non-e-simmetrico" class="text-accent hover:underline font-medium">recupero delle perdite</a>.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Gli obiettivi e il resto del patrimonio</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un fondo di emergenza già pronto, un mutuo da pagare o un reddito molto stabile cambiano la quota di rischio che ha senso prendere. L''asset allocation va pensata sul patrimonio complessivo, non sul solo conto titoli.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Due esempi, solo per orientarsi</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Prudente</strong>: circa 30% azioni, 60% obbligazioni, 10% liquidità. Oscillazioni contenute, crescita più lenta.</li><li><strong>Dinamico</strong>: circa 80% azioni, 20% obbligazioni. Oscillazioni ampie, potenziale di crescita più alto su orizzonti lunghi.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non sono raccomandazioni: la ripartizione giusta dipende dalla tua situazione. Conta soprattutto mantenerla nel tempo, con un <a href="/news/ribilanciamento-portafoglio-cosa-e-perche" class="text-accent hover:underline font-medium">ribilanciamento</a> periodico, e realizzarla con strumenti ben <a href="/news/diversificazione-portafoglio-cosa-significa-davvero" class="text-accent hover:underline font-medium">diversificati</a> e a basso costo.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti" class="text-accent hover:underline font-medium">Reflexi</a> vedi la ripartizione reale del tuo portafoglio e puoi confrontarla con quella che ti eri prefissato.</p>',
    'pubblicato',
    '2026-09-13 09:00:00',
    '2026-09-13 09:00:00'
),
(
    'sfida-52-settimane-risparmio',
    'La sfida del risparmio delle 52 settimane: come funziona e come renderla sostenibile',
    'Sfida delle 52 settimane: come funziona',
    'Un euro la prima settimana, due la seconda, fino a 52: alla fine dell''anno hai 1.378 euro da parte. Come funziona la sfida, le varianti e come evitare di abbandonarla a metà.',
    'La sfida del risparmio delle 52 settimane: come funziona, perché a fine anno hai 1.378 euro, le varianti e come non mollarla a metà strada.',
    'budget',
    '🗓️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Risparmiare una cifra fissa ogni mese è la strada più efficace, ma per molti è difficile iniziare. La sfida delle 52 settimane trasforma il risparmio in un gioco con una progressione chiara, ed è un ottimo modo per costruire l''abitudine.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ogni settimana metti da parte una somma pari al numero della settimana: 1 euro la prima, 2 la seconda, 3 la terza, fino a 52 euro nell''ultima settimana dell''anno. Sommando tutte le settimane, a fine anno avrai messo da parte <strong>1.378 euro</strong>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il bello della sfida è che all''inizio le cifre sono quasi irrilevanti, e quando diventano più consistenti l''abitudine è già consolidata.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le varianti</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Al contrario</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si parte da 52 euro e si scende fino a 1. Il totale è lo stesso, ma lo sforzo maggiore cade a inizio anno, quando la motivazione è più alta, e a dicembre, il mese più costoso, si mettono da parte pochi euro.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Moltiplicata</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se 1.378 euro ti sembrano pochi, moltiplica ogni importo: con 2 euro per settimana arrivi a 2.756 euro, con 5 a 6.890 euro. Scegli il moltiplicatore in base al tuo <a href="/news/budget-familiare-mensile-come-farlo" class="text-accent hover:underline font-medium">budget</a>, non all''entusiasmo del primo giorno.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Libera</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Stampi una tabella con i numeri da 1 a 52 e ogni settimana scegli quale cancellare: le settimane difficili scegli un numero basso, quelle buone uno alto. Alla fine li avrai usati tutti.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come non mollare a metà</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Automatizza</strong>: imposta un bonifico periodico verso un conto separato, così non devi ricordartene.</li><li><strong>Dai un nome ai soldi</strong>: un <a href="/news/obiettivi-risparmio-come-fissarli-e-raggiungerli" class="text-accent hover:underline font-medium">obiettivo concreto</a> come una vacanza o il fondo di emergenza motiva più di un numero astratto.</li><li><strong>Non toccarli</strong>: tieni i risparmi lontano dal conto delle spese quotidiane.</li><li><strong>Se salti una settimana</strong>, recuperala quando puoi invece di abbandonare tutto.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il passo successivo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La sfida è un allenamento. Una volta presa l''abitudine, conviene passare a un risparmio fisso a inizio mese, il principio del <a href="/news/paga-prima-te-stesso-risparmio-automatico" class="text-accent hover:underline font-medium">paga prima te stesso</a>, e far lavorare quei soldi nel tempo grazie all''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/obiettivi" class="text-accent hover:underline font-medium">Reflexi</a> puoi creare un obiettivo per la sfida e seguire i progressi direttamente dal tuo risparmio reale.</p>',
    'pubblicato',
    '2026-09-15 09:00:00',
    '2026-09-15 09:00:00'
),
(
    'comprare-o-affittare-casa-cosa-conviene',
    'Comprare o affittare casa: cosa conviene davvero e come fare il confronto',
    'Comprare o affittare casa: cosa conviene?',
    'Comprare non è sempre meglio che affittare, e viceversa. Il confronto corretto considera tutti i costi di entrambe le scelte, l''orizzonte e cosa faresti con i soldi dell''anticipo.',
    'Comprare o affittare casa: come confrontare davvero i costi oltre a rata e canone, e perché quanto resterai nella casa è il fattore decisivo.',
    'pianificazione',
    '🏡',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">"Pagare l''affitto è buttare soldi" è una delle frasi più ripetute sulla casa. Ma non è sempre vero: anche chi compra sostiene costi che non tornano indietro. Il confronto onesto mette a fianco tutte le spese delle due scelte, non solo il canone e la rata.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I costi di chi compra</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Gli interessi del mutuo</strong>: solo la parte di capitale della rata diventa patrimonio, gli interessi sono un costo come l''affitto.</li><li><strong>Le spese di acquisto</strong>: notaio, imposte, agenzia e <a href="/news/spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa" class="text-accent hover:underline font-medium">spese accessorie del mutuo</a>, pagate subito e non recuperabili.</li><li><strong>La manutenzione</strong>: ordinaria e straordinaria, condominio compreso. Molti usano come stima prudente circa l''1% del valore dell''immobile all''anno.</li><li><strong>Le tasse e le assicurazioni</strong> legate all''immobile, che variano molto da caso a caso.</li><li><strong>Il costo opportunità</strong>: l''anticipo e le spese, se investiti, avrebbero potuto rendere qualcosa.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I costi di chi affitta</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Il canone</strong>, che di solito viene aggiornato nel tempo.</li><li><strong>Le spese di trasloco e di cauzione</strong> a ogni cambio di casa.</li><li><strong>L''incertezza</strong>: a fine contratto il proprietario può non rinnovare.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il vantaggio principale dell''affitto è la flessibilità: cambiare città o casa costa molto meno. E i soldi che non servono per l''anticipo possono essere investiti, se lo si fa davvero con disciplina.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il fattore decisivo: quanto resterai</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le spese di acquisto si ammortizzano solo restando a lungo nella stessa casa. Se pensi di trasferirti entro pochi anni, l''affitto è spesso più conveniente; se ti vedi lì per dieci anni o più, l''acquisto tende a diventarlo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Un modo semplice per confrontare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una regola rapida è il rapporto tra prezzo della casa e affitto annuo di un immobile simile. Se il prezzo vale molte annualità di affitto, comprare costa caro rispetto all''affittare in quella zona; se ne vale poche, comprare diventa interessante. È solo un primo filtro: poi servono i numeri veri della tua situazione.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se decidi di comprare, verifica prima <a href="/news/quanto-mutuo-posso-chiedere-con-il-mio-stipendio" class="text-accent hover:underline font-medium">quanto mutuo puoi chiedere</a> e se hai diritto alle agevolazioni per i <a href="/news/mutuo-giovani-under-36-garanzia-prima-casa" class="text-accent hover:underline font-medium">mutui under 36</a>. In ogni caso, la scelta pesa sul tuo <a href="/news/patrimonio-netto-cos-e-perche-seguirlo-nel-tempo" class="text-accent hover:underline font-medium">patrimonio netto</a> per molti anni: su <a href="/patrimonio" class="text-accent hover:underline font-medium">Reflexi</a> puoi seguirlo includendo casa e mutuo.</p>',
    'pubblicato',
    '2026-09-17 09:00:00',
    '2026-09-17 09:00:00'
),
(
    'mutuo-cointestato-come-funziona',
    'Mutuo cointestato: come funziona, chi paga cosa e cosa succede in caso di separazione',
    'Mutuo cointestato: come funziona',
    'Comprare casa in due con un mutuo cointestato permette di sommare i redditi, ma lega entrambi al debito. Ecco cosa significa davvero, come si dividono rata e detrazioni e cosa fare se le cose cambiano.',
    'Mutuo cointestato: come funziona, responsabilità solidale verso la banca, quote di proprietà, detrazione degli interessi e cosa succede in caso di separazione.',
    'mutui',
    '🤝',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molte coppie, ma anche familiari o amici, comprano casa insieme con un mutuo cointestato. È spesso l''unico modo per ottenere l''importo necessario, perché la banca considera la somma dei redditi. Ma è un impegno serio, e conviene capirne bene le regole prima di firmare.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa significa cointestare un mutuo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con un mutuo cointestato tutti gli intestatari sono debitori della banca. Il punto fondamentale è la <strong>responsabilità solidale</strong>: verso la banca ognuno risponde dell''intero debito, non solo della propria metà. Se uno dei due smette di pagare, la banca può chiedere l''intera rata all''altro.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Proprietà e debito sono due cose diverse</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La quota di proprietà della casa, ad esempio 50 e 50 oppure 70 e 30, è stabilita nell''atto di acquisto e può non coincidere con quanto ciascuno contribuisce alla rata. Tra gli intestatari conviene mettere per iscritto come si dividono le spese, soprattutto se le quote sono diverse.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come si divide la detrazione degli interessi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La <a href="/news/detrazione-interessi-mutuo-prima-casa" class="text-accent hover:underline font-medium">detrazione degli interessi passivi</a> per l''abitazione principale spetta a ciascun intestatario per la propria quota di interessi, entro la propria parte del limite. Ci sono regole particolari, ad esempio quando un coniuge è fiscalmente a carico dell''altro: in caso di dubbio meglio chiedere a un CAF.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa succede in caso di separazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La fine della relazione non cancella il mutuo: la banca continua ad avere due debitori. Le strade principali sono:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Uno dei due rileva la quota dell''altro</strong> e si accolla il mutuo, se la banca accetta di liberare l''altro intestatario valutando il reddito di chi resta.</li><li><strong>Si vende la casa</strong>, si estingue il mutuo con il ricavato e si divide quanto rimane secondo le quote.</li><li><strong>Si continua a pagare insieme</strong>, soluzione possibile ma che richiede molta fiducia reciproca.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sono passaggi delicati: un accordo scritto fin dall''inizio rende tutto più semplice, come spieghiamo anche nell''articolo sulle <a href="/news/finanze-di-coppia-conti-separati-o-cointestati" class="text-accent hover:underline font-medium">finanze di coppia</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Tenere i conti chiari</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il rischio più comune è confondere la propria situazione con quella della coppia: nel bilancio personale conta la tua quota di debito e di interessi, non l''importo totale. Su <a href="/mutui" class="text-accent hover:underline font-medium">Reflexi</a> puoi indicare la tua quota di proprietà e vedere capitale residuo, interessi e rata in proporzione, con il resto delle tue finanze calcolato di conseguenza.</p>',
    'pubblicato',
    '2026-09-19 09:00:00',
    '2026-09-19 09:00:00'
),
(
    'volatilita-e-max-drawdown-misurare-il-rischio',
    'Volatilità e max drawdown: come misurare il rischio di un investimento',
    'Volatilità e max drawdown: misurare il rischio',
    'Il rendimento dice quanto puoi guadagnare, la volatilità e il drawdown quanto puoi soffrire nel frattempo. Due indicatori semplici da leggere e molto utili prima di investire.',
    'Cosa sono volatilità e max drawdown, come si leggono e perché contano quanto il rendimento quando scegli un investimento o costruisci un portafoglio.',
    'investimenti',
    '🎢',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando si confrontano due investimenti, si guarda quasi sempre il rendimento. Ma due strumenti con lo stesso rendimento medio possono offrire esperienze molto diverse: uno sale con regolarità, l''altro alterna rialzi e crolli. Per capire questa differenza servono gli indicatori di rischio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La volatilità</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La <strong>volatilità</strong> misura quanto oscillano i prezzi intorno alla loro media. Tecnicamente è la deviazione standard dei rendimenti, di solito espressa su base annua. Più è alta, più i movimenti di prezzo, al rialzo e al ribasso, sono ampi.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Come ordine di grandezza, un indice azionario globale ha storicamente una volatilità annua intorno al 15%, i titoli di Stato a breve molto meno, mentre singole azioni tecnologiche o le criptovalute possono superare di molto il 50%.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il max drawdown</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>massimo drawdown</strong> è la perdita più ampia registrata in un periodo, misurata dal punto più alto al punto più basso successivo. Se un investimento è salito fino a 100 e poi è sceso a 60 prima di riprendersi, il suo max drawdown è del 40%.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È un indicatore molto concreto: ti dice quanto avresti visto scendere il tuo capitale nel momento peggiore. E ricorda che recuperare richiede un rialzo più ampio della perdita, come spieghiamo nell''articolo sul <a href="/news/recupero-perdite-perche-non-e-simmetrico" class="text-accent hover:underline font-medium">recupero delle perdite</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come usarli</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Confronta il rischio con l''orizzonte</strong>: un drawdown del 50% è sopportabile solo se hai molti anni davanti e non dovrai vendere nel momento peggiore.</li><li><strong>Mettiti alla prova</strong>: prima di investire, chiediti cosa faresti vedendo il tuo capitale perdere quella percentuale. Se la risposta è "venderei", lo strumento è troppo rischioso per te.</li><li><strong>Guarda il portafoglio, non il singolo titolo</strong>: una buona <a href="/news/asset-allocation-cos-e-come-sceglierla" class="text-accent hover:underline font-medium">asset allocation</a> combina strumenti diversi e riduce volatilità e drawdown complessivi.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I limiti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Entrambi gli indicatori sono calcolati sul passato. Un periodo storico tranquillo può far sembrare poco rischioso uno strumento che non ha ancora affrontato una crisi. Usali per confrontare, non come garanzia. Per leggere bene anche la parte di rendimento, vedi la guida su <a href="/news/rendimento-totale-vs-cagr-come-leggere-la-performance" class="text-accent hover:underline font-medium">rendimento totale e CAGR</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nella sezione <a href="/previsioni" class="text-accent hover:underline font-medium">Previsioni di Reflexi</a> trovi volatilità annualizzata e max drawdown per ogni strumento che possiedi, accanto al trend storico, e puoi fare pratica senza rischi con la <a href="/simulazione-trading" class="text-accent hover:underline font-medium">simulazione di trading</a>.</p>',
    'pubblicato',
    '2026-09-20 09:00:00',
    '2026-09-20 09:00:00'
),
(
    'paga-prima-te-stesso-risparmio-automatico',
    'Paga prima te stesso: il metodo più semplice per risparmiare ogni mese',
    'Paga prima te stesso: come risparmiare ogni mese',
    'Invece di risparmiare quello che avanza a fine mese, metti da parte una cifra appena arriva lo stipendio. Un cambio di ordine piccolo, con effetti enormi sul risparmio.',
    'Il metodo "paga prima te stesso": cos''è, perché funziona meglio di risparmiare quello che avanza, come automatizzarlo e quanto mettere da parte ogni mese.',
    'budget',
    '🥇',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La maggior parte delle persone risparmia così: arriva lo stipendio, si pagano le spese, e quello che resta a fine mese va da parte. Il problema è che a fine mese, spesso, non resta quasi niente. Il metodo "paga prima te stesso" ribalta l''ordine, e proprio per questo funziona.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Appena ricevi lo stipendio, la prima "spesa" che paghi è il tuo risparmio: una cifra decisa in anticipo che sposti subito su un conto separato. Con quello che rimane copri tutte le altre spese del mese. Il risparmio diventa una voce fissa, come l''affitto, invece di un avanzo eventuale.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché funziona</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Toglie la decisione di mezzo</strong>: non devi scegliere ogni mese se risparmiare, è già fatto.</li><li><strong>Sfrutta un meccanismo naturale</strong>: le spese tendono a crescere fino a occupare i soldi disponibili. Se i soldi del risparmio non sono sul conto, non li spendi.</li><li><strong>Rende visibile il progresso</strong>: vedi crescere un saldo separato, ed è motivante.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come metterlo in pratica</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">1. Scegli la cifra</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Parti da una percentuale realistica dello stipendio, anche il 5 o 10%, e aumentala gradualmente. Il <a href="/news/tasso-di-risparmio-cosa-e-come-calcolarlo" class="text-accent hover:underline font-medium">tasso di risparmio</a> è l''indicatore da tenere d''occhio nel tempo.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">2. Automatizza</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Imposta un bonifico periodico dal conto principale a un conto di risparmio, programmato per il giorno successivo all''accredito dello stipendio. Una volta impostato, non devi più pensarci.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">3. Dai una destinazione ai soldi</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima il <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>, poi gli <a href="/news/obiettivi-risparmio-come-fissarli-e-raggiungerli" class="text-accent hover:underline font-medium">obiettivi</a> di medio periodo, infine l''investimento di lungo periodo, ad esempio con un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">piano di accumulo</a> che parte in automatico.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">4. Adatta il resto del budget</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le spese del mese si fanno con quello che rimane. Se all''inizio è stretto, guarda prima le <a href="/news/spese-fisse-e-variabili-differenza" class="text-accent hover:underline font-medium">spese fisse</a> che puoi ridurre.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Un''abitudine, non un sacrificio</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dopo qualche mese non noterai più la cifra che metti da parte, mentre il saldo del risparmio continuerà a crescere. Su <a href="/budget" class="text-accent hover:underline font-medium">Reflexi</a> puoi registrare il bonifico come ricorrenza e vedere a colpo d''occhio quanto ti resta per il mese dopo aver pagato prima te stesso.</p>',
    'pubblicato',
    '2026-09-22 09:00:00',
    '2026-09-22 09:00:00'
),
(
    'inflazione-dello-stile-di-vita',
    'Inflazione dello stile di vita: perché guadagni di più ma non risparmi di più',
    'Inflazione dello stile di vita: cos''è e come evitarla',
    'Ogni aumento di stipendio porta con sé nuove spese, e alla fine il risparmio resta lo stesso. È l''inflazione dello stile di vita: ecco come riconoscerla e come tenerla sotto controllo.',
    'Cos''è l''inflazione dello stile di vita, perché il risparmio resta fermo anche quando lo stipendio cresce e come evitarla con regole semplici.',
    'pianificazione',
    '🎈',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Uno stipendio più alto dovrebbe significare più risparmio. Eppure molte persone, dopo una promozione o un nuovo lavoro, si ritrovano a fine mese con lo stesso margine di prima. Il motivo ha un nome: inflazione dello stile di vita.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''<strong>inflazione dello stile di vita</strong> è la tendenza ad aumentare le spese ogni volta che aumentano le entrate. Non ha niente a che fare con l''<a href="/news/inflazione-potere-acquisto-perche-il-capitale-deve-crescere" class="text-accent hover:underline font-medium">inflazione dei prezzi</a>: qui a crescere non sono i prezzi, ma le nostre abitudini. Un''auto più nuova, una casa più grande, ristoranti più spesso, abbonamenti in più.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nessuna di queste scelte è sbagliata in sé. Il problema nasce quando avvengono in automatico, senza decidere, e assorbono tutto l''aumento.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché è così insidiosa</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>È graduale</strong>: ogni singola spesa sembra piccola e giustificata.</li><li><strong>Crea nuovi costi fissi</strong>: una rata o un affitto più alto restano anche se il reddito scende.</li><li><strong>Sposta il traguardo</strong>: più alto è il tenore di vita, più capitale serve per mantenerlo, come mostra il calcolo del <a href="/news/indipendenza-finanziaria-fire-come-calcolare-il-numero" class="text-accent hover:underline font-medium">numero FIRE</a>.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come tenerla sotto controllo</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">La regola del 50% degli aumenti</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">A ogni aumento di stipendio, destina almeno metà della differenza al risparmio e goditi l''altra metà. Migliori il tenore di vita e, allo stesso tempo, il tuo <a href="/news/tasso-di-risparmio-cosa-e-come-calcolarlo" class="text-accent hover:underline font-medium">tasso di risparmio</a> cresce.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Aumenta subito il risparmio automatico</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il momento migliore è prima di abituarti alla nuova cifra: alza il bonifico del <a href="/news/paga-prima-te-stesso-risparmio-automatico" class="text-accent hover:underline font-medium">paga prima te stesso</a> dal primo stipendio aumentato.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Distingui spese una tantum e spese fisse</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Concederti un viaggio è diverso dal prendere un impegno che durerà anni. Prima di aggiungere un nuovo costo fisso, chiediti se lo vorresti ancora se il reddito tornasse quello di prima.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Controlla le spese ricorrenti</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Gli <a href="/news/abbonamenti-dimenticati-come-scovare-spese-ricorrenti" class="text-accent hover:underline font-medium">abbonamenti</a> sono il modo più silenzioso in cui lo stile di vita si gonfia.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''<a href="/analisi" class="text-accent hover:underline font-medium">analisi predittiva di Reflexi</a> confronta la spesa media nel tempo, così vedi subito se le uscite stanno crescendo più velocemente del reddito.</p>',
    'pubblicato',
    '2026-09-24 09:00:00',
    '2026-09-24 09:00:00'
),
(
    'rinegoziazione-mutuo-come-funziona',
    'Rinegoziazione del mutuo: come funziona e quando conviene rispetto alla surroga',
    'Rinegoziazione del mutuo: come funziona',
    'Cambiare tasso, durata o tipo di mutuo senza cambiare banca: la rinegoziazione è spesso più semplice della surroga, ma dipende dalla disponibilità della tua banca. Ecco come muoversi.',
    'Rinegoziazione del mutuo: cos''è, cosa si può modificare, quanto costa, differenze con la surroga e come presentare la richiesta alla propria banca.',
    'mutui',
    '📝',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se le condizioni del tuo mutuo non ti convincono più, perché i tassi sono cambiati o la rata pesa troppo, non sei obbligato a tenerle fino alla fine. Una delle strade possibili è la rinegoziazione: modificare il contratto restando nella stessa banca.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è la rinegoziazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La <strong>rinegoziazione</strong> è un accordo tra te e la tua banca per cambiare alcune condizioni del mutuo in corso. Si può intervenire su:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Il tasso</strong>: un nuovo spread o un tasso fisso più basso.</li><li><strong>Il tipo di tasso</strong>: ad esempio passare dal variabile al fisso, se temi aumenti dell''<a href="/news/euribor-irs-mutuo-cosa-sono" class="text-accent hover:underline font-medium">Euribor</a>.</li><li><strong>La durata</strong>: allungarla abbassa la rata ma aumenta gli interessi totali; accorciarla fa l''opposto.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">L''importo del debito resta quello residuo: non si ottiene liquidità aggiuntiva.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Rinegoziazione o surroga</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con la <a href="/news/surroga-mutuo-cosa-e-come-funziona" class="text-accent hover:underline font-medium">surroga</a> porti il mutuo in un''altra banca che offre condizioni migliori, senza costi per te per legge. Con la rinegoziazione resti dove sei.</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Rinegoziazione</strong>: procedura più rapida, di solito senza notaio, ma la banca non è obbligata ad accettare e può proporti condizioni meno competitive di quelle del mercato.</li><li><strong>Surroga</strong>: ti permette di scegliere l''offerta migliore sul mercato, ma richiede una nuova istruttoria e qualche settimana in più.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Spesso le due strade si usano insieme: un''offerta di surroga da un''altra banca è l''argomento più forte per ottenere una buona rinegoziazione dalla tua.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come chiederla</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Confronta il tuo tasso con le offerte attuali, guardando il <a href="/news/tan-e-taeg-mutuo-differenza" class="text-accent hover:underline font-medium">TAEG</a> e non solo il TAN.</li><li>Raccogli una o due proposte di surroga da altre banche.</li><li>Presenta alla tua banca una richiesta scritta indicando le condizioni che vorresti.</li><li>Valuta la proposta ricevuta calcolando il risparmio complessivo, non solo la rata.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quando conviene</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Conviene soprattutto quando sei nella prima metà del mutuo, perché lì la quota di interessi è più alta. Verso la fine del piano, il risparmio si riduce e può avere più senso valutare un''<a href="/news/estinzione-anticipata-mutuo-quando-conviene" class="text-accent hover:underline font-medium">estinzione anticipata</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/mutui" class="text-accent hover:underline font-medium">Reflexi</a> puoi aggiornare tasso e durata del mutuo e vedere subito il nuovo piano di ammortamento, per confrontarlo con quello di partenza.</p>',
    'pubblicato',
    '2026-09-25 09:00:00',
    '2026-09-25 09:00:00'
),
(
    'dividendi-come-funzionano-e-come-sono-tassati',
    'Dividendi: come funzionano, come sono tassati e perché non sono un guadagno gratis',
    'Dividendi: come funzionano e come sono tassati',
    'Ricevere dividendi è piacevole, ma non sono un rendimento in più rispetto al prezzo: il valore dell''azione scende di pari importo. Ecco come funzionano e quanto pesano le tasse.',
    'Come funzionano i dividendi: data di stacco, effetto sul prezzo, tassazione al 26% in Italia, dividendi esteri ed ETF a distribuzione o ad accumulazione.',
    'investimenti',
    '💰',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molti investitori amano le azioni che pagano dividendi: arriva un accredito regolare sul conto, e sembra un guadagno che si aggiunge all''andamento del prezzo. In realtà il meccanismo è un po'' diverso, e capirlo aiuta a scegliere meglio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è un dividendo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>dividendo</strong> è la parte degli utili che un''azienda decide di distribuire agli azionisti invece di reinvestirla. Può essere pagato una o più volte l''anno, e l''importo non è garantito: l''azienda può ridurlo o sospenderlo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le date da conoscere</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Data di stacco</strong>: dal giorno di stacco l''azione viene scambiata senza diritto al dividendo. Per riceverlo devi possederla prima di quella data.</li><li><strong>Data di pagamento</strong>: il giorno in cui il dividendo viene accreditato sul conto.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché non è un guadagno gratis</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nel giorno di stacco il prezzo dell''azione scende, in linea di massima, dell''importo del dividendo: quel valore esce dall''azienda e arriva a te. Il tuo patrimonio complessivo non cambia, cambia la forma: una parte passa dal titolo alla liquidità. Per misurare correttamente un investimento serve quindi il <a href="/news/rendimento-totale-vs-cagr-come-leggere-la-performance" class="text-accent hover:underline font-medium">rendimento totale</a>, che somma andamento del prezzo e dividendi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come sono tassati in Italia</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I dividendi sono tassati al <strong>26%</strong>, come la maggior parte dei redditi finanziari, e con il regime amministrato la tassa viene trattenuta automaticamente dal broker. Sui dividendi di aziende estere, spesso, il Paese di origine applica già una ritenuta: in Italia si paga poi l''imposta sull''importo ricevuto, con il rischio di una doppia tassazione parziale. Trovi il quadro generale nella guida alla <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">tassazione degli investimenti</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Dividendi ed ETF</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Gli ETF possono distribuire i dividendi ricevuti dalle aziende in cui investono oppure reinvestirli automaticamente. Per chi è in fase di accumulo, la seconda opzione evita la tassazione a ogni distribuzione e lascia lavorare l''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>: ne parliamo nell''articolo su <a href="/news/etf-accumulazione-o-distribuzione-differenze" class="text-accent hover:underline font-medium">ETF ad accumulazione o a distribuzione</a>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quando hanno senso</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un flusso regolare di dividendi può essere utile a chi vuole un reddito dal proprio capitale, ad esempio in pensione. Scegliere un titolo solo perché paga un dividendo alto, però, è rischioso: un dividendo molto elevato a volte segnala un''azienda in difficoltà o un prezzo crollato.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti" class="text-accent hover:underline font-medium">Reflexi</a> ogni posizione mostra il rendimento calcolato sul costo medio di carico reale, con le tasse sulle plusvalenze già stimate, e i totali del portafoglio separati per valuta.</p>',
    'pubblicato',
    '2026-09-27 09:00:00',
    '2026-09-27 09:00:00'
),
(
    'budget-a-base-zero-come-funziona',
    'Budget a base zero: come funziona il metodo che dà un compito a ogni euro',
    'Budget a base zero: come funziona',
    'Con il budget a base zero ogni euro dello stipendio riceve una destinazione prima che il mese inizi: spese, risparmio, obiettivi. A fine assegnazione resta zero, ed è proprio questo il punto.',
    'Cos''è il budget a base zero (zero-based budgeting), come costruirlo passo per passo, differenze con la regola 50/30/20 e per chi è adatto questo metodo.',
    'budget',
    '0️⃣',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Molti metodi di budget fissano dei limiti di spesa e lasciano che il resto "avanzi". Il budget a base zero fa il contrario: assegna una destinazione a ogni singolo euro in entrata. Quando hai finito, entrate meno destinazioni fa esattamente zero.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">All''inizio di ogni mese parti dal reddito netto che riceverai e lo dividi tra tutte le voci, finché non resta nulla da assegnare. "Zero" non significa spendere tutto: anche il risparmio e gli investimenti sono destinazioni, e spesso sono le prime della lista.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come costruirlo passo per passo</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">1. Parti dal reddito del mese</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Usa la cifra netta che entrerà davvero. Se il reddito è variabile, basati sul mese più basso degli ultimi tempi.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">2. Assegna prima le spese fisse</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Affitto o rata, bollette, assicurazioni, abbonamenti: le <a href="/news/spese-fisse-e-variabili-differenza" class="text-accent hover:underline font-medium">spese fisse</a> sono la parte più prevedibile.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">3. Poi risparmio e obiettivi</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Decidi quanto va al <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a>, agli obiettivi e agli investimenti. Metterli prima delle spese variabili è il principio del <a href="/news/paga-prima-te-stesso-risparmio-automatico" class="text-accent hover:underline font-medium">paga prima te stesso</a>.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">4. Infine le spese variabili</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Spesa, carburante, tempo libero: quello che resta si divide tra queste voci, finché la cifra da assegnare arriva a zero. Includi anche una quota per le spese annuali, come bollo o assicurazioni, da accantonare un po'' ogni mese.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">5. Aggiusta durante il mese</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se sfori una categoria, sposti soldi da un''altra: il totale resta sempre zero. Le scelte diventano esplicite invece che subite.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Differenze con altri metodi</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La <a href="/news/regola-50-30-20-vs-budget-per-categoria" class="text-accent hover:underline font-medium">regola 50/30/20</a> divide il reddito in tre grandi blocchi ed è più veloce da impostare. Il budget a base zero è più dettagliato e richiede qualche minuto in più ogni mese, ma dà il controllo massimo. Il <a href="/news/metodo-delle-buste-budget-digitale" class="text-accent hover:underline font-medium">metodo delle buste</a> ne è in pratica una versione con contanti o conti separati.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Per chi è adatto</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Funziona molto bene per chi vuole capire esattamente dove vanno i soldi, per chi ha un obiettivo ambizioso da raggiungere o per chi esce da un periodo di difficoltà. Può risultare faticoso per chi preferisce regole semplici.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/budget" class="text-accent hover:underline font-medium">Reflexi</a> puoi assegnare un importo a ogni categoria e vedere in tempo reale quanto resta di ciascuna, con l''eventuale avanzo che si riporta al mese successivo.</p>',
    'pubblicato',
    '2026-09-29 09:00:00',
    '2026-09-29 09:00:00'
),
(
    'assicurazioni-che-servono-davvero',
    'Le assicurazioni che servono davvero: come proteggere le tue finanze senza spendere troppo',
    'Assicurazioni che servono davvero: quali scegliere',
    'Alcune assicurazioni proteggono da rischi che potrebbero mettere in crisi le tue finanze, altre coprono danni che potresti pagare da solo. Ecco come distinguerle e da dove partire.',
    'Quali assicurazioni servono davvero: il criterio per scegliere tra responsabilità civile, casa, caso morte e salute, e quelle di cui puoi fare a meno.',
    'pianificazione',
    '☂️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Le assicurazioni non sono un investimento: si pagano sperando di non usarle mai. Il loro compito è proteggerti da eventi rari ma con conseguenze economiche troppo grandi da sostenere da solo. Con questo criterio in mente, è più facile capire quali hanno senso e quali no.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il criterio: assicurare i rischi che non puoi permetterti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un danno che puoi coprire con il tuo <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a> in genere non vale una polizza. Un evento che potrebbe costarti decine o centinaia di migliaia di euro, invece, sì. Le assicurazioni utili coprono questi rischi grandi e improbabili.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quelle da valutare per prime</h2><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Responsabilità civile</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Oltre all''RC auto, obbligatoria, esiste la <strong>responsabilità civile del capofamiglia</strong>: copre i danni che tu o i tuoi familiari potreste causare ad altri nella vita quotidiana. Costa di solito poco e protegge da richieste di risarcimento potenzialmente molto alte.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">La casa</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se hai un mutuo, la polizza contro incendio e scoppio è di solito richiesta dalla banca. Vale la pena valutare anche coperture più ampie, ad esempio per danni da acqua o eventi naturali, soprattutto se la casa è la parte principale del tuo <a href="/news/patrimonio-netto-cos-e-perche-seguirlo-nel-tempo" class="text-accent hover:underline font-medium">patrimonio</a>.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Temporanea caso morte</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se qualcuno dipende dal tuo reddito, ad esempio figli o un partner con un <a href="/news/mutuo-cointestato-come-funziona" class="text-accent hover:underline font-medium">mutuo cointestato</a>, una polizza temporanea caso morte garantisce loro un capitale. È in genere economica, soprattutto se sottoscritta da giovani.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Salute e infortuni</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Possono avere senso per chi è lavoratore autonomo o ha un reddito che si fermerebbe in caso di lunga malattia. Leggi con attenzione esclusioni, franchigie e massimali.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quelle di cui spesso si può fare a meno</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Polizze su oggetti di valore contenuto, come telefoni o piccoli elettrodomestici.</li><li>Garanzie estese su prodotti già coperti dalla garanzia di legge.</li><li>Coperture vendute insieme ad altri prodotti senza che tu le abbia scelte: ricorda che per il mutuo la banca non può imporre polizze facoltative.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come tenere i conti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I premi annuali sono spese da prevedere nel <a href="/news/budget-familiare-mensile-come-farlo" class="text-accent hover:underline font-medium">budget</a>, accantonando ogni mese la quota corrispondente. Per scelte specifiche, soprattutto su vita e salute, confronta più preventivi e fatti consigliare da un professionista indipendente. Su <a href="/abbonamenti" class="text-accent hover:underline font-medium">Reflexi</a> puoi registrare i premi come spese ricorrenti, così non arrivano mai di sorpresa.</p>',
    'pubblicato',
    '2026-10-01 09:00:00',
    '2026-10-01 09:00:00'
);
